export { anatomy, parts, type ToggleGroupPart } from "./toggle-group.anatomy";
export { connect } from "./toggle-group.connect";
export {
  getFrameId,
  getIndicatorId,
  getItemEls,
  getItemId,
  getItemValues,
  getRootEl,
  getRootId,
  getScrollbarId,
  getThumbId,
} from "./toggle-group.dom";
export { machine } from "./toggle-group.machine";
export type {
  ResolvedToggleGroupMachineProps,
  ToggleGroupApi,
  ToggleGroupItemProps,
  ToggleGroupMachineProps,
  ToggleGroupSchema,
  ToggleGroupSizing,
  ToggleGroupValueChangeDetails,
} from "./toggle-group.types";

import { type Anatomy, type AnatomyPart, createAnatomy } from "../../machine/anatomy";

export type ToggleGroupPart =
  | "frame"
  | "root"
  | "label"
  | "item"
  | "indicator"
  | "scrollbar"
  | "thumb";

export const anatomy: Anatomy<ToggleGroupPart> = createAnatomy("toggle-group").parts(
  "frame",
  "root",
  "label",
  "item",
  "indicator",
  "scrollbar",
  "thumb",
);

export const parts: Record<ToggleGroupPart, AnatomyPart> = anatomy.build();

import { ariaAttr, boolAttr, dataAttr } from "../../dom/attrs";
import { resolveDir } from "../../dom/text-dir";
import { getRovingKeyAction } from "../../focus/roving-focus";
import type { NormalizeProps, PropTypes } from "../../machine/prop-types";
import type { Service } from "../../machine/types";
import { isFocusVisibleModality } from "../../nav";
import { parts } from "./toggle-group.anatomy";
import {
  getFrameId,
  getIndicatorId,
  getItemId,
  getLabelId,
  getRootEl,
  getRootId,
  getScrollbarId,
  getThumbId,
} from "./toggle-group.dom";
import type { ToggleGroupApi, ToggleGroupItemProps, ToggleGroupSchema } from "./toggle-group.types";

export function connect<T extends PropTypes>(
  service: Service<ToggleGroupSchema>,
  normalize: NormalizeProps<T>,
): ToggleGroupApi<T> {
  const { context, prop, send, scope } = service;

  const value = context.get("value");
  const groupDisabled = prop("disabled");
  const multiple = prop("multiple");
  const orientation = prop("orientation");
  const activeIndex = context.get("activeIndex");
  const contentSized = prop("sizing") === "content";
  const indicatorOffset = context.get("indicatorOffset");
  const indicatorSize = context.get("indicatorSize");
  const focusedValue = context.get("focusedValue");
  // Read once, when focus lands on an item, and held: the modality of `now`
  // flips to pointer after 300ms of mouse movement whether or not the focus
  // moved, and a ring that blinks out under the user's hands was the result.
  const focusSource = context.get("focusSource");
  const focusVisible = focusSource !== null && isFocusVisibleModality(focusSource);

  const isSelected = (item: string): boolean => value.includes(item);

  // The single tab stop, settled by the machine against the real item list.
  const tabbableValue = context.get("tabbableValue");

  return {
    value,
    disabled: groupDisabled,
    isSelected,

    setValue(next: readonly string[]): void {
      send({ type: "VALUE.SET", value: next });
    },

    getFrameProps: (): T["element"] =>
      normalize.element({
        ...parts.frame.attrs,
        id: getFrameId(scope),
        dir: prop("dir"),
        "data-orientation": orientation,
      }),

    getRootProps: (): T["element"] =>
      normalize.element({
        ...parts.root.attrs,
        id: getRootId(scope),
        dir: prop("dir"),
        // Two patterns, one presentation: single selection is a radio group,
        // multiple is a group of pressed buttons (APG).
        role: multiple ? "group" : "radiogroup",
        // Only when the label part is actually rendered: a dangling IDREF names
        // nothing and stops a consumer's own `aria-label` from winning.
        "aria-labelledby": context.get("hasLabel") ? getLabelId(scope) : undefined,
        "aria-describedby": prop("describedBy"),
        // `aria-orientation` is supported on `radiogroup` and not on `group`
        // (ARIA 1.2). The styles read `data-orientation` either way.
        "aria-orientation": multiple ? undefined : orientation,
        "data-orientation": orientation,
        "data-disabled": dataAttr(groupDisabled),
        "data-multiple": dataAttr(multiple),
        // Only in `"content"`, so the markup of the default sizing is untouched.
        "data-sizing": contentSized ? "content" : undefined,
        // The pill is placed from the measurement below, and the count is what
        // gates it into view.
        style: {
          "--sui-segment-count": String(Math.max(context.get("itemCount"), 1)),
          // On the root because the root is the indicator's containing block: the
          // offset is measured against that box, and an `inset` resolves against
          // the same one.
          "--sui-indicator-offset": indicatorOffset !== null ? `${indicatorOffset}px` : undefined,
          "--sui-indicator-size": indicatorSize !== null ? `${indicatorSize}px` : undefined,
        },
      }),

    getLabelProps: (): T["element"] =>
      normalize.element({ ...parts.label.attrs, id: getLabelId(scope) }),

    getIndicatorProps: (): T["element"] =>
      normalize.element({
        ...parts.indicator.attrs,
        id: getIndicatorId(scope),
        "aria-hidden": ariaAttr(true),
        "data-orientation": orientation,
        // Nothing to point at — either nothing is selected, or several things
        // are and one travelling pill cannot honestly represent them. In
        // multiple mode the selected items carry their own background instead.
        "data-empty": dataAttr(activeIndex < 0 || multiple),
        // The pill must not play a spring because the page has only just been
        // painted or a segment was added. It has to be on the markup that first
        // carries the real numbers, not removed in the same commit that writes
        // them: a transition compares two computed styles and reads its property
        // list off the second one, so an attribute that leaves as the position
        // arrives animates exactly the frame it was meant to suppress.
        "data-immediate": dataAttr(!context.get("indicatorAnimated")),
      }),

    getScrollbarProps: (): T["element"] =>
      normalize.element({
        ...parts.scrollbar.attrs,
        id: getScrollbarId(scope),
        "aria-hidden": ariaAttr(true),
        "data-orientation": "horizontal",
      }),

    getThumbProps: (): T["element"] =>
      normalize.element({ ...parts.thumb.attrs, id: getThumbId(scope) }),

    getItemProps: (itemProps: ToggleGroupItemProps): T["button"] => {
      const { value: itemValue } = itemProps;
      const selected = isSelected(itemValue);
      const disabled = groupDisabled || itemProps.disabled === true;
      const focused = focusedValue === itemValue;

      return normalize.button({
        ...parts.item.attrs,
        id: getItemId(scope, itemValue),
        type: "button",
        disabled,
        // The value lives on the element because the DOM is where the item order
        // is read from — this is what lets the machine stay out of a registry.
        "data-value": itemValue,
        // Read by the styles, never by the machine: it is what the width
        // reservation is rendered from.
        "data-label": itemProps.label,
        role: multiple ? undefined : "radio",
        "aria-checked": multiple ? undefined : boolAttr(selected),
        "aria-pressed": multiple ? boolAttr(selected) : undefined,
        // Tri-state, like the toolbar, and for a reason the toolbar does not
        // have: the stop is chosen by `syncItems` from the item order, which is
        // read from the DOM. A prerendered group has no DOM to read, so writing
        // `-1` on every item — the selected one included — took the whole
        // control out of the tab order until hydration. Absent, the items are
        // buttons and keep their natural order; the roving stop appears with
        // the first sync.
        tabIndex: tabbableValue === null ? undefined : itemValue === tabbableValue ? 0 : -1,
        "data-state": selected ? "on" : "off",
        "data-disabled": dataAttr(disabled),
        "data-orientation": orientation,
        "data-focus-visible": dataAttr(focused && focusVisible),
        // On the focused item only: the composite has one focus, and an
        // attribute claiming otherwise on every segment describes nothing.
        "data-focus-source": focused ? (focusSource ?? undefined) : undefined,
        onClick(event) {
          if (event.defaultPrevented || disabled) return;
          send({ type: "ITEM.CLICK", value: itemValue });
        },
        onKeyDown(event) {
          if (event.defaultPrevented || event.altKey || event.ctrlKey || event.metaKey) return;
          // Shift+arrow is the range-selection gesture and belongs to the
          // component that has ranges; here it means nothing, and consuming it
          // would move the focus while a selection was being extended.
          if (event.shiftKey) return;
          // The key map is pure, so `connect` may resolve it: that is what lets
          // the arrow be prevented from scrolling the page only when it was
          // actually claimed.
          // APG: in a radio group Right *or* Down moves to and checks the next
          // item, whatever the orientation. A group of independent toggles keeps
          // to its own axis, so the other one still scrolls the page.
          const action = getRovingKeyAction(event.key, {
            orientation,
            dir: resolveDir(prop("dir"), getRootEl(scope)),
            bothAxes: !multiple,
          });
          if (action === null) return;
          event.preventDefault();
          send({ type: "ITEM.NAVIGATE", action, value: itemValue });
        },
        onFocus(event) {
          if (event.defaultPrevented) return;
          send({ type: "ITEM.FOCUS", value: itemValue });
        },
        onBlur(event) {
          if (event.defaultPrevented) return;
          send({ type: "ITEM.BLUR" });
        },
      });
    },
  };
}

import { query, queryAll } from "../../dom/query";
import { getPartId } from "../../machine/ids";
import type { Scope } from "../../machine/scope";

const COMPONENT = "toggle-group";

export function getFrameId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "frame");
}

export function getRootId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "root");
}

export function getLabelId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "label");
}

export function getIndicatorId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "indicator");
}

export function getItemId(scope: Scope, value: string): string {
  return getPartId(scope, COMPONENT, "item", value);
}

export function getScrollbarId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "scrollbar");
}

export function getThumbId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "thumb");
}

export function getRootEl(scope: Scope): HTMLElement | null {
  return scope.getById(getRootId(scope));
}

export function getScrollbarEl(scope: Scope): HTMLElement | null {
  return scope.getById(getScrollbarId(scope));
}

export function getThumbEl(scope: Scope): HTMLElement | null {
  return scope.getById(getThumbId(scope));
}

/**
 * The item order is the DOM order, read when it is needed rather than kept in a
 * registry the consumer would have to maintain. A composite that has to be told
 * about its own children is a composite that goes out of sync the first time one
 * is added conditionally.
 */
export function getItemEls(scope: Scope): HTMLElement[] {
  const root = getRootEl(scope);
  if (root === null) return [];
  return queryAll<HTMLElement>(root, '[data-part~="toggle-group:item"]');
}

export function getItemValues(scope: Scope): string[] {
  return getItemEls(scope).map((item) => item.dataset.value ?? "");
}

export function getItemEl(scope: Scope, value: string): HTMLElement | null {
  return getItemEls(scope).find((item) => item.dataset.value === value) ?? null;
}

/**
 * `aria-labelledby` may only point at an id that exists, so whether the label
 * part was rendered is a fact to read rather than assume.
 */
export function hasLabel(scope: Scope): boolean {
  return query(getRootEl(scope), '[data-part~="toggle-group:label"]') !== null;
}

/**
 * The segmented control, and the sliding pill that is the design system's
 * signature. Two things are worth stating.
 *
 * **The item list is read from the DOM, never registered.** A composite that has
 * to be told about its own children goes out of sync the first time one is
 * rendered conditionally. Roving needs the order, the indicator needs the index,
 * and both come from `[data-part~="toggle-group:item"]` under the root — re-read when the value
 * changes and whenever the children do.
 *
 * **The pill is measured, in every sizing.** A column is as wide as the room and
 * the labels make it, and a group that scrolls along its line has a visible track
 * narrower than the whole one, so no index or percentage can name a segment. The
 * active item's layout box is read against the root, and the root, every item and
 * the web fonts are watched for the moment it moves.
 *
 * **Single and multiple are different ARIA patterns, not a flag on one.** Single
 * selection is a radio group, where arrows move *and* select; multiple is a group
 * of pressed buttons, where arrows only move and Space selects. The machine
 * implements both because APG says they are two patterns, and the presentation
 * happens to be identical.
 */

import { observeChildren, observeResize } from "../../dom/observers";
import { resolveDir } from "../../dom/text-dir";
import { getInitialIndex, getNextIndex } from "../../focus/roving-focus";
import { trackInlineScrollbar } from "../../interaction/inline-scrollbar";
import { scrollIntoInlineView, trackInlineScrollEdges } from "../../interaction/scroll-edges";
import { createMachine } from "../../machine/create-machine";
import type { Machine, MachineParams } from "../../machine/types";
import { focusElement, getInputModality, trackInputModality } from "../../nav";
import type { InputModality } from "../../types";
import { measureIndicator } from "../../utils/indicator-rect";
import {
  getItemEl,
  getItemEls,
  getItemValues,
  getRootEl,
  getScrollbarEl,
  getThumbEl,
  hasLabel,
} from "./toggle-group.dom";
import type { ToggleGroupSchema } from "./toggle-group.types";

/**
 * Where the pill belongs, read from layout against the root — the indicator's
 * own containing block, so the number the sheet consumes as an `inset` and the
 * number measured here cannot disagree. `null` when there is nothing to point at:
 * several things are selected, or none, or the item is not in the DOM.
 *
 * **Measured to a fraction of a pixel where the rects can be trusted**
 * (`measureIndicator`), and from the layout boxes, whole pixels, where they
 * cannot: a segment springs to `--sui-press-scale` while it is pressed, which is
 * exactly when the choice is measured, and a bounding rect would carry that scale
 * into the number. The sheet positions the root, so a segment's `offsetParent` is
 * the root; one that is not (hidden, or wrapped in a positioned element) has no
 * box to point at and measures `null`.
 */
function readIndicatorMetrics({
  context,
  prop,
  scope,
}: Pick<MachineParams<ToggleGroupSchema>, "context" | "prop" | "scope">): {
  offset: number | null;
  size: number | null;
} {
  const root = getRootEl(scope);
  const value = prop("multiple") ? undefined : context.get("value")[0];
  const item = value === undefined ? null : getItemEl(scope, value);
  if (root === null || item === null) return { offset: null, size: null };

  if (item.offsetParent !== root) return { offset: null, size: null };

  const vertical = prop("orientation") === "vertical";
  const rtl = resolveDir(prop("dir"), root) === "rtl";
  const measured = measureIndicator(root, item, scope.getComputedStyle, {
    orientation: vertical ? "vertical" : "horizontal",
    dir: rtl ? "rtl" : "ltr",
  });
  if (measured !== null) return measured;

  if (vertical) return { offset: item.offsetTop, size: item.offsetHeight };
  return {
    offset: rtl ? root.clientWidth - item.offsetLeft - item.offsetWidth : item.offsetLeft,
    size: item.offsetWidth,
  };
}

export const machine: Machine<ToggleGroupSchema> = createMachine<ToggleGroupSchema>({
  props({ props }) {
    return {
      orientation: "horizontal",
      multiple: false,
      disabled: false,
      // A radio group has no deselect, and single mode is a radio group (APG).
      // Multiple mode is a set of independent toggles, where clicking an on item
      // is the only way to turn it off.
      deselectable: props.multiple ?? false,
      loopFocus: true,
      sizing: "equal",
      ...props,
    };
  },

  context({ prop, bindable }) {
    return {
      value: bindable<readonly string[]>(() => ({
        defaultValue: prop("defaultValue") ?? [],
        value: prop("value"),
        // Order is not meaning here: a segmented control that reports a change
        // because the same two values arrived the other way round would loop.
        isEqual: (a, b) => a.length === b.length && a.every((entry) => b.includes(entry)),
        onChange: (value) => prop("onValueChange")?.({ value }),
        debugLabel: "toggle-group value",
      })),
      activeIndex: bindable<number>(() => ({ defaultValue: -1 })),
      itemCount: bindable<number>(() => ({ defaultValue: 0 })),
      tabbableValue: bindable<string | null>(() => ({ defaultValue: null })),
      focusedValue: bindable<string | null>(() => ({ defaultValue: null })),
      focusSource: bindable<InputModality | null>(() => ({ defaultValue: null })),
      hasLabel: bindable<boolean>(() => ({ defaultValue: false })),
      // False until a sync proves the value moved rather than the track, which
      // makes the first paint a snap: `tabs` draws the same line with the same
      // default (`tabs.machine.ts`, `indicatorAnimated`).
      indicatorAnimated: bindable<boolean>(() => ({ defaultValue: false })),
      indicatorOffset: bindable<number | null>(() => ({ defaultValue: null })),
      indicatorSize: bindable<number | null>(() => ({ defaultValue: null })),
    };
  },

  initialState() {
    return "idle";
  },

  effects: ["trackModality", "trackItems", "trackIndicator", "trackScrollEdges", "trackScrollbar"],

  watch({ context, prop, scope, track, action }) {
    // The item list is a dependency like any other. Reading it here means an
    // adapter that re-renders keeps the indicator in step synchronously, and the
    // observer below is left to cover the mutations no render caused.
    //
    // The separator is spelled out rather than typed: the raw byte used to sit
    // in this file, which made ripgrep call the whole module binary and skip it
    // — every grep in the repo, and every review agent built on one, has been
    // blind to this file. It stays U+0000 because that is the one character an
    // attribute value cannot carry (the HTML parser rewrites it to U+FFFD), so
    // two different item lists can never key the same.
    track(
      () => [context.get("value"), getItemValues(scope).join("\u0000"), hasLabel(scope)],
      () => action(["syncItems", "syncIndicator"]),
    );

    // A change of sizing, axis or direction is a layout the measured pill has to
    // be re-read for. It is a layout and never a choice: it lands where it
    // belongs rather than travelling.
    track(
      () => [prop("sizing"), prop("orientation"), prop("dir")],
      () => action(["settleIndicator", "syncIndicator"]),
    );
  },

  on: {
    "ITEM.CLICK": { guard: "isInteractive", actions: ["selectItem", "revealItem"] },
    "VALUE.SET": { actions: ["setValue"] },
    "ITEM.FOCUS": { actions: ["setFocusedValue"] },
    "ITEM.BLUR": { actions: ["clearFocus"] },
    "ITEM.NAVIGATE": { guard: "isInteractive", actions: ["navigate"] },
    "ITEMS.SYNC": { actions: ["syncItems", "remeasureIndicator"] },
    "INDICATOR.MEASURE": { actions: ["remeasureIndicator"] },
  },

  states: {
    idle: {},
  },

  implementations: {
    guards: {
      isInteractive: ({ prop }) => !prop("disabled"),
    },

    actions: {
      selectItem({ context, prop, event }) {
        if (event.type !== "ITEM.CLICK") return;
        const current = context.get("value");
        const selected = current.includes(event.value);

        if (prop("multiple")) {
          context.set(
            "value",
            selected ? current.filter((entry) => entry !== event.value) : [...current, event.value],
          );
          return;
        }
        if (selected && !prop("deselectable")) return;
        context.set("value", selected ? [] : [event.value]);
      },

      setValue({ context, event }) {
        if (event.type === "VALUE.SET") context.set("value", event.value);
      },

      setFocusedValue({ context, event, scope }) {
        if (event.type !== "ITEM.FOCUS") return;
        context.set("focusedValue", event.value);
        // Tab leaves and comes back to where the user was, not to the start.
        context.set("tabbableValue", event.value);
        // Read here and held: an arrow key moving between items is a new focus,
        // so the source follows a keyboard user across the composite, while a
        // mouse merely crossing the page never touches it.
        context.set("focusSource", getInputModality(scope.getDoc()));
      },

      clearFocus({ context }) {
        context.set("focusedValue", null);
        context.set("focusSource", null);
      },

      /**
       * A segment chosen ends inside the window, as one the arrows reach does: a
       * click on a segment the edge cuts used to check it and leave it cut. On the
       * click and not on the focus, which a pointer brings at `pointerdown`: a
       * segment that moved before the button came up would take the release away
       * from the press. Not after an arrow either, whose `navigate` has already
       * scrolled to the same segment.
       */
      revealItem({ prop, scope, event }) {
        if (event.type !== "ITEM.CLICK" || event.origin === "navigate") return;
        if (prop("orientation") === "vertical") return;
        const item = getItemEl(scope, event.value);
        if (item !== null) scrollIntoInlineView(getRootEl(scope), item);
      },

      navigate({ context, prop, scope, event, send }) {
        if (event.type !== "ITEM.NAVIGATE") return;
        const items = getItemEls(scope);
        const current = items.findIndex((item) => item.dataset.value === event.value);
        const next = getNextIndex(current, event.action, {
          count: items.length,
          loop: prop("loopFocus"),
          isDisabled: (index) => items[index]?.hasAttribute("disabled") === true,
        });
        const target = items[next];
        if (target === undefined || next === current) return;

        focusElement(target);
        if (prop("orientation") !== "vertical") scrollIntoInlineView(getRootEl(scope), target);
        // Single selection follows the focus: in a radio group the arrow keys
        // choose, they do not merely visit (APG). In multiple mode they only
        // move, and Space is what selects.
        const value = target.dataset.value ?? "";
        context.set("tabbableValue", value);
        if (!prop("multiple")) send({ type: "ITEM.CLICK", value, origin: "navigate" });
      },

      // The index the indicator is gated by has to be a fact about the DOM rather
      // than about the value array (motion.md §2.9). The tab
      // stop is settled here too: without one the whole composite would be
      // unreachable by Tab until something had been selected.
      syncItems({ context, scope }) {
        const items = getItemEls(scope);
        const values = getItemValues(scope);
        const selected = context.get("value")[0];
        const labelled = hasLabel(scope);

        // This is the only place that can tell the two apart, which is why the
        // decision lives here and not in the actions that commit a value: if the
        // segment count or the label changed, what moved the pill is the track,
        // and a track that changes shape must not be chased across the control.
        // The first sync is always one of those — the count goes 0 -> n — so a
        // freshly painted group snaps into place instead of sliding in from
        // `--sui-segment-count: 1`, which puts it a full track-width off-screen.
        //
        // Both branches are conditional, and neither may become an `else`: this
        // action runs again whenever the observer reports and nothing has to have
        // changed for it to. A sync that moves nothing must leave the flag where
        // it was, or the second one of a mount would arm the very spring the
        // first one disarmed.
        const nextIndex = selected === undefined ? -1 : values.indexOf(selected);
        const trackChanged =
          values.length !== context.get("itemCount") || labelled !== context.get("hasLabel");
        if (trackChanged) context.set("indicatorAnimated", false);
        else if (nextIndex !== context.get("activeIndex")) {
          context.set("indicatorAnimated", true);
        }

        context.set("activeIndex", nextIndex);
        context.set("itemCount", values.length);
        context.set("hasLabel", labelled);

        // The composite exposes exactly one tab stop, and it has to be an item
        // the browser will actually stop on: parked on a disabled button, the
        // only `tabindex="0"` is skipped and the whole control falls out of the
        // tab order.
        const isDisabled = (index: number): boolean =>
          items[index]?.hasAttribute("disabled") === true;
        const enabled = (value: string | undefined): boolean => {
          const index = value === undefined ? -1 : values.indexOf(value);
          return index !== -1 && !isDisabled(index);
        };

        const tabbable = context.get("tabbableValue");
        if (enabled(tabbable ?? undefined)) return;
        const first = getInitialIndex({ count: items.length, isDisabled });
        context.set(
          "tabbableValue",
          enabled(selected) ? (selected ?? null) : (values[first] ?? null),
        );
      },

      /**
       * Run after `syncItems` has decided the latch from the index, so a choice
       * travels and a changed track snaps exactly as in `"equal"` sizing. The one
       * thing added is the empty state, in both directions: a pill arriving from
       * nowhere has no position to travel from and would slide in from
       * `inset-inline-start: 0`, and one leaving for nowhere would slide there and
       * shrink to nothing while it fades.
       */
      syncIndicator(params) {
        const { context } = params;
        const { offset, size } = readIndicatorMetrics(params);
        if (context.get("indicatorOffset") === null || offset === null) {
          context.set("indicatorAnimated", false);
        }
        context.set("indicatorOffset", offset);
        context.set("indicatorSize", size);
      },

      settleIndicator({ context }) {
        context.set("indicatorAnimated", false);
      },

      /**
       * The observers' own path, and the only one that compares instead of
       * consulting: a remeasure that finds the pill where it already was is not an
       * event, and lowering the latch on it would cancel the spring a choice had
       * just armed — `ResizeObserver` delivers the size it was armed with at the
       * first rendering opportunity, which lands after the first click a person
       * can make.
       */
      remeasureIndicator(params) {
        const { context } = params;
        const { offset, size } = readIndicatorMetrics(params);

        if (offset !== context.get("indicatorOffset") || size !== context.get("indicatorSize")) {
          context.set("indicatorAnimated", false);
        }
        context.set("indicatorOffset", offset);
        context.set("indicatorSize", size);
      },
    },

    effects: {
      // No listener: the source is read once, when focus lands, so a modality
      // change no longer has to reach every mounted control. Holding the handle
      // is the whole job — the tracker has to be running before the first Tab.
      trackModality({ scope }) {
        return trackInputModality(scope.getDoc());
      },

      trackItems({ scope, send }) {
        send({ type: "ITEMS.SYNC" });
        // Items appear and disappear with the app's own state; the indicator has
        // to survive that without the consumer telling anyone.
        return observeChildren(getRootEl(scope), () => send({ type: "ITEMS.SYNC" }));
      },

      /**
       * A group wider than the room it is given scrolls along its inline axis, and
       * a hidden scrollbar says nothing about it: the sheet fades the edge this
       * attribute names. Written on the root, which is the scroller.
       */
      trackScrollEdges({ prop, scope, send }) {
        return trackInlineScrollEdges(getRootEl(scope), {
          active: () => prop("orientation") !== "vertical" && !prop("disabled"),
          attributes: ["data-disabled"],
          onToggle: () => send({ type: "INDICATOR.MEASURE" }),
        });
      },

      /**
       * The drawn bar of that scroller: a part outside it that a `Frame` places, so a
       * group without one simply has nothing to bind.
       */
      trackScrollbar({ scope }) {
        return trackInlineScrollbar(getRootEl(scope), getScrollbarEl(scope), getThumbEl(scope));
      },

      /**
       * The root and every item are observed, never "the active one" — a segment
       * is as wide as its label, and a label that changes inside a root of fixed
       * width moves the pill without the root's own box changing. A text node
       * edited in place is a `characterData` mutation, which `trackItems` does not
       * see either, and a web font arriving late changes every width at once.
       */
      trackIndicator({ scope, send }) {
        let disposed = false;
        const measure = (): void => {
          if (!disposed) send({ type: "INDICATOR.MEASURE" });
        };

        const root = getRootEl(scope);
        const stopRoot = observeResize(root, measure);
        const observeItems = (): VoidFunction => {
          const stops = getItemEls(scope).map((item) => observeResize(item, measure));
          return (): void => {
            for (const stop of stops) stop();
          };
        };

        let stopItems = observeItems();
        // Re-armed rather than re-measured: the measurement on a child mutation is
        // already `trackItems`' job.
        const stopChildren = observeChildren(root, () => {
          stopItems();
          stopItems = observeItems();
        });

        // A one-shot, and the flag is why the disposer sets one at all: the
        // promise outlives the effect, and a measurement after teardown is a
        // `send` into a stopped service.
        void scope.getDoc().fonts?.ready.then(measure);

        return () => {
          disposed = true;
          stopChildren();
          stopItems();
          stopRoot();
        };
      },
    },
  },
});

import type { RovingAction } from "../../focus/roving-focus";
import type { PropTypes } from "../../machine/prop-types";
import type { MachineSchema } from "../../machine/types";
import type { Direction, InputModality, Orientation } from "../../types";

export interface ToggleGroupValueChangeDetails {
  readonly value: readonly string[];
}

export type ToggleGroupSizing = "equal" | "content";

export interface ToggleGroupItemProps {
  readonly value: string;
  readonly disabled?: boolean | undefined;
  /**
   * The item's own text, repeated so the styles can reserve the width the label
   * takes at the selected weight. Without it the segment widens when it is
   * selected, the track grows, and the indicator — measured before the weight
   * changed — lands beside the segment it points at. Omitting it is safe:
   * the weight change is gated on the attribute being there.
   */
  readonly label?: string | undefined;
}

export interface ToggleGroupMachineProps {
  /** Not defaulted, deliberately: left unset the resolved page direction governs, so a subtree inside an RTL region inherits instead of being reset to `ltr`. */
  readonly dir?: Direction | undefined;
  readonly orientation?: Orientation | undefined;
  /** Controlled. Always an array — single selection is an array of at most one. */
  readonly value?: readonly string[] | undefined;
  readonly defaultValue?: readonly string[] | undefined;
  readonly multiple?: boolean | undefined;
  readonly disabled?: boolean | undefined;
  /**
   * Whether clicking the selected item clears it. Defaults to `multiple`: a
   * radio group has no deselect, and single mode *is* a radio group. Turning it
   * on makes a nullable control, which is no longer the APG pattern.
   */
  readonly deselectable?: boolean | undefined;
  readonly loopFocus?: boolean | undefined;
  /**
   * `"equal"` cuts the track into equal columns, `"content"` sizes each segment
   * by its own label; the pill is placed from a measurement of the active
   * segment's layout box either way. A group can switch at runtime. A horizontal
   * group wider than its room scrolls along its line; nothing folds.
   */
  readonly sizing?: ToggleGroupSizing | undefined;
  /** Ids of the text describing this control — a `field` supplies them. */
  readonly describedBy?: string | undefined;
  readonly onValueChange?: ((details: ToggleGroupValueChangeDetails) => void) | undefined;
}

export interface ResolvedToggleGroupMachineProps extends ToggleGroupMachineProps {
  readonly orientation: Orientation;
  readonly multiple: boolean;
  readonly disabled: boolean;
  readonly deselectable: boolean;
  readonly loopFocus: boolean;
  readonly sizing: ToggleGroupSizing;
}

export interface ToggleGroupSchema extends MachineSchema {
  state: "idle";
  props: ResolvedToggleGroupMachineProps;
  context: {
    value: readonly string[];
    /** Where the sliding indicator sits. `-1` when nothing is selected. */
    activeIndex: number;
    /** How many segments there are — the indicator's width is one of them. */
    itemCount: number;
    /** Where the single tab stop sits — the selected item, or the first one. */
    tabbableValue: string | null;
    /** The item that actually holds DOM focus, if any. */
    focusedValue: string | null;
    focusSource: InputModality | null;
    hasLabel: boolean;
    /** False while the track itself changed — a first paint, a segment added, a
     * label arriving. The pill travels for a choice and snaps for a layout. */
    indicatorAnimated: boolean;
    /** Where the pill starts and how long it is, measured from the active segment. `null` until read, and for no selection. */
    indicatorOffset: number | null;
    indicatorSize: number | null;
  };
  event:
    | { type: "ITEM.CLICK"; value: string; origin?: "navigate" }
    | { type: "ITEM.FOCUS"; value: string }
    | { type: "ITEM.BLUR" }
    | { type: "ITEM.NAVIGATE"; action: RovingAction; value: string }
    | { type: "VALUE.SET"; value: readonly string[] }
    | { type: "ITEMS.SYNC" }
    | { type: "INDICATOR.MEASURE" };
  action:
    | "selectItem"
    | "revealItem"
    | "setValue"
    | "setFocusedValue"
    | "clearFocus"
    | "navigate"
    | "syncItems"
    | "syncIndicator"
    | "settleIndicator"
    | "remeasureIndicator";
  guard: "isInteractive";
  effect: "trackModality" | "trackItems" | "trackIndicator" | "trackScrollEdges" | "trackScrollbar";
}

export interface ToggleGroupApi<T extends PropTypes = PropTypes> {
  readonly value: readonly string[];
  readonly disabled: boolean;
  isSelected(value: string): boolean;
  setValue(value: readonly string[]): void;
  getFrameProps(): T["element"];
  getRootProps(): T["element"];
  getLabelProps(): T["element"];
  getIndicatorProps(): T["element"];
  getScrollbarProps(): T["element"];
  getThumbProps(): T["element"];
  getItemProps(props: ToggleGroupItemProps): T["button"];
}

/**
 * `<ToggleGroup options={…}/>` — a root, a label, a sliding indicator, and a row
 * of items, all four of `toggle-group.anatomy.ts`. Unlike `select` or `menu`,
 * `ToggleGroupRoot` renders a real element (`toggle-group.tsx:44-62`, the `root`
 * part), so this is the `Pagination`/`Button` shape — a root plus a collection —
 * never the context-only shape.
 *
 * One translation the type system cannot make on its own, and it is an a11y
 * defect if it is skipped: an item's `label` is **both** the width-reservation
 * text (`data-label`, read by the styles so a selected segment does not widen
 * the whole track — `toggle-group.connect.ts:128-130`) **and** the text the
 * segment shows. `value` stays the item's identity alone — the machine reads
 * item order and selection off it — and is never what names the button. The two
 * are easy to conflate because they are both strings on the same entry; keeping
 * them apart is the entire translation this layer does.
 *
 * `label` at the top is the group's own visible name (`ToggleGroupLabel`,
 * `"Basic"` in the stories), optional and placed only when given — the same
 * shape as `Dialog.closeLabel`: the machine wires `aria-labelledby` on its own
 * once it has read the part off the DOM (`hasLabel`, `toggle-group.dom.ts:51-53`),
 * so a group named some other way (`aria-label`, a `Field`'s legend) simply
 * never gets the part. There is no `icon` slot: the anatomy has one leading
 * track and it is the whole button, not a cell inside it — a segmented control's
 * items are text, exactly as every story here writes them.
 */

import type { ToggleGroupItemProps as CoreToggleGroupItemProps } from "@standarui/core/toggle-group";
import type { ReactNode } from "react";
import type { PartProps } from "../../create-part";
import { splitProps } from "../../split-props";
import {
  MACHINE_PROPS,
  ToggleGroupFrame,
  ToggleGroupIndicator,
  ToggleGroupItem,
  ToggleGroupLabel,
  ToggleGroupRoot,
  ToggleGroupScrollbar,
  ToggleGroupThumb,
  type UseToggleGroupProps,
} from "./toggle-group";

/**
 * One segment. An intersection, never a `Pick`, so a field added to
 * `ToggleGroupItemProps` shows up here without anyone thinking about it —
 * `label` is narrowed from optional to required, because this is the only place
 * both meanings of it (the drawn text, the reserved width) come from.
 */
export type ToggleGroupOption = Omit<CoreToggleGroupItemProps, "value" | "label"> & {
  readonly value: string;
  readonly label: string;
};

/**
 * The escape hatch, applied **last** on every part: the layer's own defaults are
 * defaults, and the consumer's entry wins over them.
 */
export interface ToggleGroupParts {
  /**
   * The outer box, which is the item of a flex or a grid parent: the layout of the
   * group (`flex: none`, `align-self`, a width) goes here, while `className` and
   * `style` on the group itself stay on the root.
   */
  readonly frame?: PartProps<"div", UseToggleGroupProps> | undefined;
  readonly scrollbar?: PartProps<"div"> | undefined;
  readonly thumb?: PartProps<"div"> | undefined;
  readonly label?: PartProps<"span"> | undefined;
  readonly indicator?: PartProps<"div"> | undefined;
  /**
   * Applied to EVERY item, hence no `value`, `label` or `disabled` — the entry's
   * own fields, excluded through `Own` the way `ToggleGroupItemProps` itself
   * excludes them — and no `id` **or IDREF**: one id repeated down a group is a
   * broken reference per segment, and one `aria-labelledby` repeated gives every
   * segment the same name, which no dangling-IDREF check can see because the id
   * it points at does resolve. `ref` goes for the same reason: a single ref held
   * by N segments ends up holding the last one.
   */
  readonly item?:
    | Omit<
        PartProps<"button", CoreToggleGroupItemProps>,
        "id" | "ref" | "aria-labelledby" | "aria-describedby" | "aria-controls"
      >
    | undefined;
}

export interface ToggleGroupComposedProps
  extends UseToggleGroupProps,
    Omit<PartProps<"div", UseToggleGroupProps>, "children"> {
  /**
   * The group's own visible name. The part is placed only when this is given —
   * left out, nothing is added, and the group is named some other way instead
   * (`aria-label`, a `Field`'s legend), exactly as the machine's own
   * `hasLabel` read expects.
   */
  readonly label?: ReactNode;
  readonly options: readonly ToggleGroupOption[];
  readonly parts?: ToggleGroupParts | undefined;
}

export function ToggleGroup(props: ToggleGroupComposedProps): ReactNode {
  const { label, options, parts, ...rest } = props;
  const [machineProps, root] = splitProps(rest, MACHINE_PROPS);

  return (
    <ToggleGroupFrame {...machineProps} {...parts?.frame}>
      <ToggleGroupRoot {...root}>
        {label == null ? null : <ToggleGroupLabel {...parts?.label}>{label}</ToggleGroupLabel>}
        {/* Written first so it paints under the items it slides beneath. */}
        <ToggleGroupIndicator {...parts?.indicator} />
        {options.map((option) => (
          <ToggleGroupItem key={option.value} {...option} {...parts?.item}>
            {option.label}
          </ToggleGroupItem>
        ))}
      </ToggleGroupRoot>
      <ToggleGroupScrollbar {...parts?.scrollbar}>
        <ToggleGroupThumb {...parts?.thumb} />
      </ToggleGroupScrollbar>
    </ToggleGroupFrame>
  );
}

export type {
  ToggleGroupMachineProps,
  ToggleGroupSizing,
  ToggleGroupValueChangeDetails,
} from "@standarui/core/toggle-group";
export {
  ToggleGroup,
  type ToggleGroupComposedProps,
  type ToggleGroupOption,
  type ToggleGroupParts,
} from "./composed";
export {
  type ToggleGroupApi,
  ToggleGroupFrame,
  type ToggleGroupFrameProps,
  ToggleGroupIndicator,
  ToggleGroupItem,
  type ToggleGroupItemProps,
  ToggleGroupLabel,
  ToggleGroupRoot,
  type ToggleGroupRootProps,
  ToggleGroupScrollbar,
  ToggleGroupThumb,
  type UseToggleGroupProps,
  useToggleGroup,
} from "./toggle-group";

import { isDev, warn } from "@standarui/core";
import * as toggleGroup from "@standarui/core/toggle-group";
import { createContext, type ReactNode, useContext } from "react";
import { createPart, type PartProps } from "../../create-part";
import { inheritFromField, useFieldContext } from "../../field-context";
import { normalizeProps, type ReactPropTypes } from "../../normalize-props";
import { createPartContext } from "../../part-context";
import { splitProps } from "../../split-props";
import { type MachineRuntimeProps, useMachine } from "../../use-machine";
import { useRender } from "../../use-render";

export type ToggleGroupApi = toggleGroup.ToggleGroupApi<ReactPropTypes>;

const ToggleGroupContext = createPartContext<ToggleGroupApi>("ToggleGroup");

export interface UseToggleGroupProps
  extends toggleGroup.ToggleGroupMachineProps,
    MachineRuntimeProps {}

export function useToggleGroup(props: UseToggleGroupProps): ToggleGroupApi {
  return toggleGroup.connect(useMachine(toggleGroup.machine, props), normalizeProps);
}

export const MACHINE_PROPS = [
  "id",
  "ids",
  "getRootNode",
  "dir",
  "orientation",
  "value",
  "defaultValue",
  "multiple",
  "disabled",
  "deselectable",
  "loopFocus",
  "sizing",
  "describedBy",
  "onValueChange",
] as const;

export interface ToggleGroupFrameProps
  extends UseToggleGroupProps,
    PartProps<"div", UseToggleGroupProps> {}

const ToggleGroupFrameContext = createContext<ToggleGroupApi | null>(null);

/**
 * The outer box that owns the machine, so the scroller and the drawn bar can be
 * siblings inside it: a bar that scrolls with its scroller, or is masked by it, is
 * no bar. Optional: a parts tree of `ToggleGroupRoot` alone owns its machine as it
 * always did and draws no bar.
 */
export function ToggleGroupFrame(props: ToggleGroupFrameProps): ReactNode {
  const [machineProps, rest] = splitProps(props, MACHINE_PROPS);
  const { render, asChild, children, ...elementProps } = rest;
  const field = useFieldContext();
  const api = useToggleGroup(inheritFromField(machineProps, field));

  return (
    <ToggleGroupContext.Provider value={api}>
      <ToggleGroupFrameContext.Provider value={api}>
        {useRender({
          render,
          asChild,
          element: "div",
          props: api.getFrameProps(),
          elementProps,
          children,
        })}
      </ToggleGroupFrameContext.Provider>
    </ToggleGroupContext.Provider>
  );
}

export interface ToggleGroupRootProps
  extends UseToggleGroupProps,
    PartProps<"div", UseToggleGroupProps> {}

function OwnedToggleGroupRoot(props: ToggleGroupRootProps): ReactNode {
  const [machineProps, rest] = splitProps(props, MACHINE_PROPS);
  const { render, asChild, children, ...elementProps } = rest;
  const field = useFieldContext();
  const api = useToggleGroup(inheritFromField(machineProps, field));

  return (
    <ToggleGroupContext.Provider value={api}>
      <ToggleGroupFrameContext.Provider value={null}>
        {useRender({
          render,
          asChild,
          element: "div",
          props: api.getRootProps(),
          elementProps,
          children,
        })}
      </ToggleGroupFrameContext.Provider>
    </ToggleGroupContext.Provider>
  );
}

function FramedToggleGroupRoot({
  api,
  ...props
}: ToggleGroupRootProps & { readonly api: ToggleGroupApi }): ReactNode {
  const [machineProps, rest] = splitProps(props, MACHINE_PROPS);
  const { render, asChild, children, ...elementProps } = rest;

  warn(
    isDev() && Object.keys(machineProps).length > 0,
    "ToggleGroupRoot: inside a `ToggleGroupFrame` the frame owns the machine, so the machine props given here (`value`, `multiple`, `disabled`…) are ignored. Pass them to the frame.",
  );

  return (
    <ToggleGroupFrameContext.Provider value={null}>
      {useRender({
        render,
        asChild,
        element: "div",
        props: api.getRootProps(),
        elementProps,
        children,
      })}
    </ToggleGroupFrameContext.Provider>
  );
}

export function ToggleGroupRoot(props: ToggleGroupRootProps): ReactNode {
  const frame = useContext(ToggleGroupFrameContext);
  return frame === null ? (
    <OwnedToggleGroupRoot {...props} />
  ) : (
    <FramedToggleGroupRoot {...props} api={frame} />
  );
}

export const ToggleGroupLabel: (props: PartProps<"span">) => ReactNode = createPart(
  ToggleGroupContext,
  { name: "ToggleGroupLabel", element: "span", props: (api) => api.getLabelProps() },
);

export const ToggleGroupIndicator: (props: PartProps<"div">) => ReactNode = createPart(
  ToggleGroupContext,
  { name: "ToggleGroupIndicator", element: "div", props: (api) => api.getIndicatorProps() },
);

export const ToggleGroupScrollbar: (props: PartProps<"div">) => ReactNode = createPart(
  ToggleGroupContext,
  { name: "ToggleGroupScrollbar", element: "div", props: (api) => api.getScrollbarProps() },
);

export const ToggleGroupThumb: (props: PartProps<"div">) => ReactNode = createPart(
  ToggleGroupContext,
  { name: "ToggleGroupThumb", element: "div", props: (api) => api.getThumbProps() },
);

export interface ToggleGroupItemProps
  extends toggleGroup.ToggleGroupItemProps,
    PartProps<"button", toggleGroup.ToggleGroupItemProps> {}

/**
 * The one part with props of its own: an item is identified by its value, and
 * the machine reads the rest — its position, its neighbours — from the DOM.
 */
export function ToggleGroupItem(props: ToggleGroupItemProps): ReactNode {
  const [itemProps, rest] = splitProps(props, ["value", "disabled", "label"]);
  const { render, asChild, children, ...elementProps } = rest;
  const api = ToggleGroupContext.usePart("ToggleGroupItem");

  return useRender({
    render,
    asChild,
    element: "button",
    props: api.getItemProps(itemProps),
    elementProps,
    children,
  });
}
